namespace sv_8859e613f6a34ba2a47dbd75d24a7d3c;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@rendermode InteractiveServer

<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    @ThemeLabel
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeLabel => Theme?.Theme switch
    {
        Theme.Dark => "🌙 Dark",
        Theme.System => "💻 System",
        _ => "☀️ Light"
    };
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width: 200px;"
            value="@currentTheme" @onchange="OnThemeChanged">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@currentAccent" @onchange="OnAccentChanged" />
</div>

<p>
    Current: <strong>@currentTheme</strong> /
    <span style="color: @currentAccent;">@currentAccent</span>
</p>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme currentTheme;
    private string currentAccent = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme;
            currentAccent = Theme.AccentColor;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        currentTheme = Enum.Parse<Theme>((string)e.Value!);
        await PushUpdate();
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        currentAccent = (string)e.Value!;
        await PushUpdate();
    }

    private async Task PushUpdate()
    {
        var updated = new ThemeInfo
        {
            Theme = currentTheme,
            AccentColor = currentAccent
        };
        await ThemeSource.NotifyChangedAsync(updated);
    }
}

